<?php $incident = $incidentDetail; $incidentDeliveries = \Monitor\Models\NotificationRepository::forIncident((int) $incident['id']); ?>
<div class="monitor-detail-grid"><section class="panel"><div class="panel-header"><div><h2><?= e($incident['monitor_name']) ?></h2><p>Incident #<?= (int) $incident['id'] ?></p></div><a class="monitor-back-link" href="<?= e(admin_url('incidents')) ?>">All incidents</a></div>
<div class="incident-summary"><span class="pill <?= $incident['status'] === 'open' ? 'pill-danger' : 'pill-success' ?>"><?= $incident['status'] === 'open' ? 'Active outage' : 'Resolved' ?></span><strong><?= e(incident_duration($incident)) ?></strong></div>
<div class="detail-stats">
<div><small>Monitor</small><strong><a href="<?= e(admin_url('monitors/view') . '?id=' . (int) $incident['monitor_id']) ?>"><?= e($incident['monitor_name']) ?></a></strong></div>
<div><small>Started (first failure)</small><strong><?= e(display_date($incident['started_at'])) ?></strong></div>
<div><small>Detected (confirmed Down)</small><strong><?= e(display_date($incident['detected_at'])) ?></strong></div>
<div><small>Recovered</small><strong><?= $incident['recovered_at'] ? e(display_date($incident['recovered_at'])) : 'Not yet' ?></strong></div>
<div><small>Failed scheduled checks</small><strong><?= (int) $incident['failure_count'] ?></strong></div>
<div><small>Latest HTTP status</small><strong><?= $incident['last_http_status'] === null ? 'Unavailable' : (int) $incident['last_http_status'] ?></strong></div>
<div><small>Opening check</small><strong><?= $incident['opening_check_id'] ? '#' . (int) $incident['opening_check_id'] : 'Unavailable' ?></strong></div>
<div><small>Closing check</small><strong><?= $incident['closing_check_id'] ? '#' . (int) $incident['closing_check_id'] : 'Not yet' ?></strong></div></div>
<?php if ($incident['last_error_type'] || $incident['last_error_message']): ?><div class="monitor-diagnostic-result test-fail-panel"><strong><?= e($incident['last_error_type'] ?: 'Failure details') ?></strong><span><?= e($incident['last_error_message'] ?: 'No additional information.') ?></span></div><?php endif; ?>
<div class="form-section"><h3>Notification delivery</h3>
<?php if (!$incidentDeliveries): ?><p class="field-help">No Telegram notifications were queued for this incident.</p><?php else: ?>
<div class="health-list"><?php foreach ($incidentDeliveries as $delivery): ?><div class="health-item"><span><?= e(strtoupper($delivery['event_type'])) ?> · <?= e(ucfirst($delivery['channel'])) ?> · <?= $delivery['recipient_type']==='portal_user' ? 'Portal User' : 'Admin / Global · '.e($delivery['destination_chat_id']) ?></span><div><strong><?= e(ucfirst($delivery['status'])) ?></strong> <small><?= (int) $delivery['attempt_count'] ?> attempt(s)</small></div></div><?php endforeach; ?></div><?php endif; ?></div>
</section>
<section class="panel"><div class="panel-header"><div><h2>Related scheduled checks</h2><p>Up to 30 recent records. Old raw checks may expire under the retention setting.</p></div></div>
<?php if (!$incidentChecks): ?><div class="monitor-awaiting">No raw checks available for this incident.</div><?php else: ?><div class="monitor-table-scroll"><table class="monitor-table"><thead><tr><th>Time</th><th>Result</th><th>HTTP</th><th>Response</th><th>Attempts</th><th>Reason</th></tr></thead><tbody><?php foreach ($incidentChecks as $check): ?><tr><td data-label="Time"><?= e(display_date($check['checked_at'])) ?></td><td data-label="Result"><span class="pill <?= $check['success'] ? 'pill-success' : 'pill-danger' ?>"><?= $check['success'] ? 'Recovered' : 'Failed' ?></span></td><td data-label="HTTP"><?= $check['http_status'] === null ? '—' : (int) $check['http_status'] ?></td><td data-label="Response"><?= $check['response_time_ms'] === null ? '—' : (int) $check['response_time_ms'] . ' ms' ?></td><td data-label="Attempts"><?= (int) $check['attempt_count'] ?></td><td data-label="Reason"><?= e($check['error_type'] ?: '—') ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section></div>
